def create_project():
    for rel, parts in FILES.items():
        content = base64.b64decode("".join(parts))
        d = os.path.dirname(rel)
        if d: os.makedirs(d, exist_ok=True)
        open(rel, "wb").write(content)
        print(f"  created  {rel}")
    print(f"\n✓ {len(FILES)} files created.")
    print("\nRun:  streamlit run dashboard/app.py")
if __name__ == "__main__":
    create_project()
